# owner: platform
import unittest

from hourglass.rounding import label_rounded_spans
from hourglass.models import Span

class LabelTests(unittest.TestCase):
    def test_rounds_edges_to_nearest_step(self):
        self.assertEqual(
            label_rounded_spans([Span(537, 1035)], 15), ["09:00-17:15 (8h 15m)"]
        )

    def test_exact_half_rounds_up(self):
        self.assertEqual(
            label_rounded_spans([Span(545, 600)], 10), ["09:10-10:00 (0h 50m)"]
        )

    def test_step_of_one_keeps_minutes(self):
        self.assertEqual(
            label_rounded_spans([Span(541, 1019)], 1), ["09:01-16:59 (7h 58m)"]
        )

    def test_end_of_day_rounds_to_24_00(self):
        self.assertEqual(
            label_rounded_spans([Span(1400, 1439)], 60), ["23:00-24:00 (1h 00m)"]
        )

    def test_each_span_gets_a_label(self):
        spans = [Span(539, 1051), Span(60, 120)]
        self.assertEqual(
            label_rounded_spans(spans, 60),
            ["09:00-18:00 (9h 00m)", "01:00-02:00 (1h 00m)"],
        )

    def test_empty_input(self):
        self.assertEqual(label_rounded_spans([], 15), [])

    def test_span_that_rounds_to_nothing(self):
        with self.assertRaises(ValueError):
            label_rounded_spans([Span(541, 549)], 30)

class StepTests(unittest.TestCase):
    def test_steps_that_divide_an_hour(self):
        for step in (1, 2, 3, 4, 5, 6, 10, 12, 15, 20, 30, 60):
            with self.subTest(step=step):
                self.assertEqual(label_rounded_spans([], step), [])

    def test_rejects_zero_negative_and_uneven_steps(self):
        for step in (0, -15, 7, 25, 120, 1.5):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    label_rounded_spans([], step)
